import math


def impurity(labels, criterion="gini"):
    if not labels or any(x not in (0, 1) for x in labels):
        raise ValueError("Nonempty binary labels")
    p = sum(labels) / len(labels)
    if criterion == "gini":
        return 2 * p * (1 - p)
    if criterion != "entropy":
        raise ValueError("Unknown criterion")
    return -sum(q * math.log2(q) for q in (p, 1 - p) if q > 0)


assert impurity([1, 1]) == 0
assert impurity([0, 1], "entropy") == 1
assert impurity([0, 0, 0, 1]) == 0.375
print(impurity([0, 0, 0, 1], "entropy"))

# একদম সহজ Recursive CART Classifier (কোনো numpy বা pandas ছাড়াই!)
def gini_score(labels):
    if len(labels) == 0:
        return 0.0
    ones = 0
    for v in labels:
        ones += v
    p = ones / len(labels)
    return 2.0 * p * (1.0 - p)

def majority_class(labels):
    ones = 0
    for v in labels:
        ones += v
    return 1 if ones >= len(labels) - ones else 0

def fit_cart(X_data, y_data, depth=0, max_depth=2, min_leaf=1):
    # Stopping Condition: বিশুদ্ধ Leaf বা সর্বোচ্চ গভীরতা
    parent_g = gini_score(y_data)
    if parent_g == 0.0 or depth >= max_depth or len(y_data) < 2 * min_leaf:
        return {"is_leaf": True, "pred": majority_class(y_data), "samples": len(y_data)}

    num_features = len(X_data[0])
    best_gain = 0.0
    best_split = None

    for f in range(num_features):
        vals = []
        for row in X_data:
            vals.append(row[f])
        unique_v = sorted(set(vals))
        for k in range(len(unique_v) - 1):
            th = (unique_v[k] + unique_v[k + 1]) / 2.0
            X_L, y_L, X_R, y_R = [], [], [], []
            for i in range(len(X_data)):
                if X_data[i][f] <= th:
                    X_L.append(X_data[i])
                    y_L.append(y_data[i])
                else:
                    X_R.append(X_data[i])
                    y_R.append(y_data[i])
            if len(y_L) < min_leaf or len(y_R) < min_leaf:
                continue
            w_child = (len(y_L) / len(y_data)) * gini_score(y_L) + (len(y_R) / len(y_data)) * gini_score(y_R)
            gain = parent_g - w_child
            if gain > best_gain:
                best_gain = gain
                best_split = (f, th, X_L, y_L, X_R, y_R)

    if best_split is None:
        return {"is_leaf": True, "pred": majority_class(y_data), "samples": len(y_data)}

    f, th, X_L, y_L, X_R, y_R = best_split
    return {
        "is_leaf": False,
        "feature": f,
        "threshold": th,
        "left": fit_cart(X_L, y_L, depth + 1, max_depth, min_leaf),
        "right": fit_cart(X_R, y_R, depth + 1, max_depth, min_leaf),
    }

def predict_one(node, row):
    if node["is_leaf"]:
        return node["pred"]
    if row[node["feature"]] <= node["threshold"]:
        return predict_one(node["left"], row)
    return predict_one(node["right"], row)

X_train = [[1, 5], [2, 6], [3, 2], [4, 1], [5, 7], [6, 8]]
y_train = [0, 0, 1, 1, 0, 0]

tree = fit_cart(X_train, y_train, max_depth=2, min_leaf=1)
preds = []
for row in X_train:
    preds.append(predict_one(tree, row))

print("Root Split: feature", tree["feature"], "<=", tree["threshold"])
print("Training Predictions:", preds, "| Exact Match:", preds == y_train)

