import math


def effective_alpha(node_risk, subtree_risk, leaves):
    if (
        leaves <= 1
        or not all(math.isfinite(x) for x in (node_risk, subtree_risk))
        or not 0 <= subtree_risk <= node_risk
    ):
        raise ValueError("Valid non-leaf risk contract")
    return (node_risk - subtree_risk) / (leaves - 1)


answer = effective_alpha(0.5, 0.2, 3)
assert math.isclose(0.5 + answer, 0.2 + answer * 3)
