import math

tree = {"feature": 0, "threshold": 2.5, "left": {"p": 0.0}, "right": {"p": 1.0}}


def predict(node, row):
    if any(not math.isfinite(x) for x in row):
        raise ValueError("Finite row")
    while "feature" in node:
        node = (
            node["left"] if row[node["feature"]] <= node["threshold"] else node["right"]
        )
    return node["p"]


assert predict(tree, [2.5]) == 0
answer = predict(tree, [3.0])
print(answer)
